function validate([n, m, hBars, vBars]) {
  if (!Number.isInteger(n) || n < 1 || n > 1e9) return 'n is between 1 and 10^9.';
  if (!Number.isInteger(m) || m < 1 || m > 1e9) return 'm is between 1 and 10^9.';
  if (hBars.length < 1 || hBars.length > 100) return 'hBars needs 1 to 100 values.';
  if (vBars.length < 1 || vBars.length > 100) return 'vBars needs 1 to 100 values.';
  if (hBars.some(v => !Number.isInteger(v) || v < 2 || v > n + 1)) return 'Each hBars value is between 2 and n + 1.';
  if (vBars.some(v => !Number.isInteger(v) || v < 2 || v > m + 1)) return 'Each vBars value is between 2 and m + 1.';
  if (new Set(hBars).size !== hBars.length) return 'The values in hBars must be distinct.';
  if (new Set(vBars).size !== vBars.length) return 'The values in vBars must be distinct.';
  return null;
}

