function maximizeSquareHoleArea(n, m, hBars, vBars) {
  function longestGap(bars) {
    bars.sort((a, b) => a - b);
    let run = 1;
    let best = 1;
    for (let i = 1; i < bars.length; i++) {
      if (bars[i] === bars[i - 1] + 1) {
        run++;
      } else {
        run = 1;
      }
      best = Math.max(best, run);
    }
    return best + 1;
  }

  const side = Math.min(longestGap(hBars), longestGap(vBars));
  return side * side;
}

