function maximizeSquareHoleArea(n, m, hBars, vBars) {
  // A side s needs s - 1 removable bars in a row in both directions.
  const fits = (bars, s) => {
    const removable = new Set(bars);
    if (s === 1) return true;
    for (const start of bars) {
      let ok = true;
      for (let k = 0; k < s - 1; k++) if (!removable.has(start + k)) { ok = false; break; }
      if (ok) return true;
    }
    return false;
  };
  for (let s = 102; s >= 1; s--) if (fits(hBars, s) && fits(vBars, s)) return s * s;
  return 1;
}

