function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const bars = (limit, count) => {
    // Values lie in 2..limit + 1 and come in clustered runs so long streaks appear.
    const chosen = new Set();
    while (chosen.size < count) {
      const start = pick(2, limit + 1);
      const length = pick(1, size === 'large' ? 30 : 4);
      for (let v = start; v < start + length && v <= limit + 1 && chosen.size < count; v++) chosen.add(v);
    }
    const list = [...chosen];
    for (let i = list.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [list[i], list[j]] = [list[j], list[i]]; }
    return list;
  };
  if (size === 'large') {
    const n = rand() < 0.5 ? pick(100, 200) : pick(100000000, 1000000000);
    const m = rand() < 0.5 ? pick(100, 200) : pick(100000000, 1000000000);
    return [n, m, bars(n, pick(60, 100)), bars(m, pick(60, 100))];
  }
  const n = pick(1, 8);
  const m = pick(1, 8);
  return [n, m, bars(n, pick(1, n)), bars(m, pick(1, m))];
}
